mapper.select:
SELECT f.*, a.name AS account_name, w.name AS warehouse_name, mt.name AS material_name, o.outbound_no, i.inbound_no, p.package_no
FROM ecom_owh_fee f
JOIN ecom_owh_account a ON a.id = f.account_id
LEFT JOIN wms_warehouse w ON w.id = f.warehouse_id
LEFT JOIN wms_material mt ON mt.id = f.material_id
LEFT JOIN ecom_owh_outbound o ON o.id = f.outbound_id
LEFT JOIN ecom_package p ON p.id = o.package_id
LEFT JOIN ecom_owh_inbound i ON i.id = f.inbound_id

    AND f.account_id = #{accountId}
    AND f.fee_type = #{feeType}
    AND f.status = #{status}
    AND f.fee_date >= #{begin}
    AND f.fee_date <= #{end}

        AND (f.ref_no LIKE CONCAT('%', #{keyword}, '%') OR f.sku LIKE CONCAT('%', #{keyword}, '%')
             OR f.post_target LIKE CONCAT('%', #{keyword}, '%') OR o.outbound_no LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY f.fee_date DESC, f.id DESC

SELECT YEAR(f.fee_date) * 100 + MONTH(f.fee_date) AS "period", f.fee_type AS "feeType",
       SUM(COALESCE(f.amount_base, 0)) AS "amount", COUNT(*) AS "cnt"
FROM ecom_owh_fee f

    AND f.account_id = #{accountId}
    AND f.fee_date >= #{begin}
    AND f.fee_date <= #{end}

GROUP BY YEAR(f.fee_date) * 100 + MONTH(f.fee_date), f.fee_type
ORDER BY 1
